  ('creature', 'devil-skull', 'Weapon', 'By weapon', 1, 'melee', 'Uses any weapon, -1 with mechanical ones; prefers swords, clubs and magic weapons.', 1),
  ('creature', 'magic-beetle', 'Bite', '3D6 M.D.', 1, 'melee', NULL, 1),
  ('creature', 'jinn-africa', 'Restrained punch', '4D6 S.D.C.', 0, 'melee', 'plus P.S. bonus', 1),
