  ('creature', 'chest-amalgamate', 'Chest mouth bite', '1D6 M.D.', 1, 'melee', 'or 1D6X10 S.D.C.; plus poison 2D6X10 S.D.C. (6D6 M.D.)', 4),
  ('creature', 'wildebeest', 'Running ram', '4D6', 0, 'melee', 'Counts as two attacks', 1),
