  ('creature', 'cape-buffalo', 'Running ram', '4D6', 0, 'melee', 'Counts as two attacks', 1),
  ('creature', 'cape-buffalo', 'Head butt', '2D4', 0, 'melee', NULL, 2),
  ('creature', 'cape-buffalo', 'Kick/stomp', '2D4', 0, 'melee', NULL, 3),
  ('creature', 'cape-buffalo', 'Trample', '3D6', 0, 'melee', NULL, 4),
  ('creature', 'african-lion', 'Claws (female)', '2D6', 0, 'melee', NULL, 1),
  ('creature', 'african-lion', 'Bite (female)', '2D4', 0, 'melee', NULL, 2),
  ('creature', 'african-lion', 'Bite (male)', '4D4', 0, 'melee', NULL, 3),
  ('creature', 'african-lion', 'Claws (male)', '3D6', 0, 'melee', NULL, 4),
  ('creature', 'leopard', 'Claws', '2D4', 0, 'melee', NULL, 1),
